function bytesAndHash(text) {
  const bytes = Buffer.from(text, "utf8");
  return { bytes: bytes.length, sha256: crypto.createHash("sha256").update(bytes).digest("hex") };
}
function assertIdentity(text, expectedBytes, expectedSha, label) {
  const actual = bytesAndHash(text);
  if (actual.bytes !== expectedBytes || actual.sha256 !== expectedSha)
    throw new Error("The complete text identity differs: " + label);
}
function replay(text, hunks, reverse = false) {
  const lines = text.split("\n"), output = [];
  let at = 0;
  for (const hunk of hunks) {
    const start = reverse ? hunk.new_start : hunk.old_start;
    const before = reverse ? hunk.new : hunk.old;
    const after = reverse ? hunk.old : hunk.new;
    if (!Number.isInteger(start) || start < at ||
        JSON.stringify(lines.slice(start, start + before.length)) !== JSON.stringify(before))
      throw new Error("A complete pinned hunk no longer matches at line " + start);
    output.push(...lines.slice(at, start), ...after);
    at = start + before.length;
  }
  output.push(...lines.slice(at));
  return output.join("\n");
}
function readUtf8(file) {
  const bytes = fs.readFileSync(file);
  const text = bytes.toString("utf8");
  if (!Buffer.from(text, "utf8").equals(bytes))
    throw new Error("The source is not canonical UTF-8: " + file);
  return text;
}
function parseArguments() {
  const result = { verify_existing: false };
  for (let i = 2; i < process.argv.length; i++) {
    const key = process.argv[i];
    if (key === "--verify-existing") result.verify_existing = true;
    else if (key === "--repo" || key === "--outdir") {
      if (++i >= process.argv.length) throw new Error("A path argument is missing");
      result[key.slice(2)] = path.resolve(process.argv[i]);
    } else throw new Error("Unknown argument: " + key);
  }
  if (!result.repo || !result.outdir)
    throw new Error("Both --repo and --outdir are required");
  return result;
}
function inside(root, relative) {
  if (path.isAbsolute(relative) || relative.split("/").includes(".."))
    throw new Error("The stored relative path is invalid");
  const resolved = path.resolve(root, relative);
  if (!resolved.startsWith(root + path.sep))
    throw new Error("The stored path leaves its root");
  return resolved;
}
function main() {
  const args = parseArguments();
  const prepared = [];
  for (const spec of SPECIFICATIONS) {
    const inputPath = inside(args.repo, spec.parent_path);
    const outputPath = inside(args.outdir, spec.output_path);
    const parent = readUtf8(inputPath);
    assertIdentity(parent, spec.parent_bytes, spec.parent_sha256, spec.parent_path);
    const result = replay(parent, spec.hunks);
    assertIdentity(result, spec.output_bytes, spec.output_sha256, spec.output_path);
    if (replay(result, spec.hunks, true) !== parent)
      throw new Error("Whole reverse reconstruction failed for " + spec.role);
    prepared.push({ spec, inputPath, outputPath, parent, result });
  }
  // Re-read all complete parents after reconstruction and before any writes.
  for (const item of prepared) {
    const parent = readUtf8(item.inputPath);
    assertIdentity(parent, item.spec.parent_bytes, item.spec.parent_sha256, item.spec.parent_path);
    if (parent !== item.parent) throw new Error("A parent changed while reconstructing");
  }
  // Preflight only output text collisions; this is not a scientific preflight.
  for (const item of prepared) {
    if (fs.existsSync(item.outputPath)) {
      const existing = readUtf8(item.outputPath);
      assertIdentity(existing, item.spec.output_bytes, item.spec.output_sha256, item.spec.output_path);
    } else if (args.verify_existing) {
      throw new Error("The complete existing output is absent: " + item.spec.output_path);
    }
  }
  for (const item of prepared) {
    if (!args.verify_existing && !fs.existsSync(item.outputPath)) {
      fs.mkdirSync(path.dirname(item.outputPath), { recursive: true });
      fs.writeFileSync(item.outputPath, item.result, { encoding: "utf8", flag: "wx" });
    }
    const actual = readUtf8(item.outputPath);
    assertIdentity(actual, item.spec.output_bytes, item.spec.output_sha256, item.spec.output_path);
  }
  process.stdout.write(JSON.stringify({
    schema: SCHEMA, complete: true,
    mode: args.verify_existing ? "compare-all-complete-existing-texts" : "reconstruct-all-complete-texts",
    whole_parent_and_child_sha256_checked: true,
    whole_reverse_text_reconstruction_checked: true,
    scientific_execution: false, Python_import_or_AST_or_compilation: false,
    solver_sources_or_queue_modified: false,
    outputs: prepared.map(({ spec, outputPath }) => ({
      role: spec.role, path: outputPath, bytes: spec.output_bytes,
      sha256: spec.output_sha256, protected_git_blob: spec.output_git_blob_sha,
      parent_path: spec.parent_path, parent_bytes: spec.parent_bytes,
      parent_sha256: spec.parent_sha256, parent_git_blob: spec.parent_git_blob_sha
    }))
  }, null, 2) + "\n");
}
main();
